/**
 * One scenario per check of invoice-out-build-standard, for Docket Billing.
 *
 * Generated by `npx @aipathway/conformance init invoice-out-build-standard`, from
 * https://aipathway.com.au/explore-ai/invoice-out-build-standard, then filled
 * in. The checks are fetched at run time; what is here is the world each check
 * starts in, how the build is driven, and what "held" means.
 *
 * The world is a civil and earthmoving subcontractor on Xero. Each job's lines
 * are the lines of the site dockets filed against it, each naming its docket
 * number (SD-...). Schedule of rates codes (AUD, ex GST):
 *   MOB-SITE    mobilisation to site (callout)
 *   CREW-HR     crew labour, per hour (labour)
 *   PLANT-EX5   5 t excavator with operator, per hour (labour, wet hire)
 *   PLANT-TIP   tipper truck with driver, per hour (labour, wet hire)
 *   MAT-RB20    20 mm road base, per tonne (material)
 *   DW-CREW     daywork crew hours outside the contract scope (variation)
 *   MAT-AG100   a code the schedule does not hold
 *
 * The runner plays the outside world between runs: the job system marking a
 * job complete, the clock moving, and the accounts person releasing a draft.
 * Every holds() returns a strict boolean.
 */

import { InvoiceOutWorld } from "@aipathway/conformance";

const HOUR = 3_600_000;
const PERSON = "Kylie Brennan, accounts";
const BOOK = {
  edition: "schedule-of-rates-2026-10",
  items: [
    { code: "MOB-SITE", description: "Mobilisation to site", rate: 350 },
    { code: "CREW-HR", description: "Crew labour, per hour", rate: 92 },
    { code: "PLANT-EX5", description: "5 t excavator with operator, per hour", rate: 155 },
    { code: "PLANT-TIP", description: "Tipper with driver, per hour", rate: 130 },
    { code: "MAT-RB20", description: "20 mm road base, per tonne", rate: 48 },
    { code: "DW-CREW", description: "Daywork crew hours, per hour", rate: 105 },
  ],
};
const RULE = { name: "Under $2,000, released by Kylie Brennan's rule", threshold: 2000 };
const done = (id, lines, extra = {}) => ({ id, customerId: `HC-${id}`, status: "complete", completedAt: "2026-10-30T06:00:00.000Z", lines, ...extra });
let docketSeq = 4400;
const line = (code, qty, kind, extra = {}) => ({ code, qty, kind, description: `site docket SD-${++docketSeq}`, ...extra });
const rateOf = (code) => BOOK.items.find((i) => i.code === code)?.rate;

const tick = (build, world) => build(world.ports(), { type: "job.completed" });
const personReleases = (build, world, jobId) => build(world.ports(), { type: "release", jobId, person: PERSON });

const writes = (world) => world.calls.filter((c) => c.port === "write_invoice");
const creates = (world, jobId) => writes(world).filter((c) => c.request?.jobId === jobId && !c.request?.update);
const idx = (world, pred) => world.calls.findIndex(pred);
const sendIdx = (world, invId) => idx(world, (c) => c.port === "issue_notice" && c.request?.send === invId);
const releaseIdx = (world, invId, pred = () => true) => idx(world, (c) => c.port === "gate" && c.request?.release === invId && pred(c.request));
const sentOnes = (world) => new Set(world.sends.map((s) => s.invoiceId));
const describe = (world) =>
  `${world.calls.length} port call(s); invoices ${world.invoices.map((i) => `${i.jobId}:${i.status}${i.parkReason ? `/${i.parkReason}` : ""}`).join(" ") || "none"}; escalations ${world.escalations.map((e) => e.reason).join(" ") || "none"}; sends ${world.sends.length}`;

/** Every send in the world was preceded by a release of that invoice. */
const everySendReleased = (world) =>
  world.calls.every((c, i) => c.port !== "issue_notice" || world.calls.slice(0, i).some((r) => r.port === "gate" && r.request?.release === c.request?.send && (r.request.person || r.request.rule)));

export const scenarios = [
  {
    checkId: "completion-is-the-trigger",
    // 1. Two jobs marked complete today, one still open with dockets on it. Two invoices, each written after a read that showed its job complete.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("JB-3101", [line("MOB-SITE", 1, "callout")]),
          done("JB-3102", [line("CREW-HR", 8, "labour")]),
          { id: "JB-3103", customerId: "HC-JB-3103", status: "open", lines: [line("PLANT-EX5", 6, "labour")] },
        ],
      }),
    drive: tick,
    holds: (world) => {
      const ws = writes(world);
      const tracedToCompleteRead = ws.every((c) => {
        const at = world.calls.indexOf(c);
        return world.calls.slice(0, at).some((r) => r.port === "read_job" && r.request?.jobs === true && (r.response?.complete ?? []).includes(c.request?.jobId));
      });
      return (
        world.invoices.length === 2 &&
        world.invoicesFor("JB-3101").length === 1 &&
        world.invoicesFor("JB-3102").length === 1 &&
        world.invoicesFor("JB-3103").length === 0 &&
        ws.length >= 2 &&
        tracedToCompleteRead
      );
    },
    describe,
  },
  {
    checkId: "lines-come-from-the-job",
    // 2. Mobilisation, two crew hours and road base, each off a signed docket: the invoice carries those
    // three codes and quantities and no others, and names the docket each came from.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("JB-3110", [
            line("MOB-SITE", 1, "callout", { description: "site docket SD-3110-A" }),
            line("CREW-HR", 2, "labour", { description: "site docket SD-3110-A" }),
            line("MAT-RB20", 12.5, "material", { description: "site docket SD-3110-B" }),
          ]),
        ],
      }),
    drive: tick,
    holds: (world) => {
      const inv = world.invoicesFor("JB-3110");
      if (inv.length !== 1 || inv[0].status === "parked") return false;
      const got = inv[0].lines.map((l) => `${l.code}x${l.qty}:${l.kind}`).sort().join("|");
      const notes = inv[0].notes ?? "";
      const traced = ["MOB-SITE x1 from SD-3110-A", "CREW-HR x2 from SD-3110-A", "MAT-RB20 x12.5 from SD-3110-B"].every((t) => notes.includes(t));
      return got === ["MOB-SITEx1:callout", "CREW-HRx2:labour", "MAT-RB20x12.5:material"].sort().join("|") && traced;
    },
    describe,
  },
  {
    checkId: "rates-only-from-the-book",
    // 3. One job's docket carries agg pipe the schedule does not hold; another is fully priced, plant hours included.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("JB-3120", [line("PLANT-EX5", 4, "labour"), line("MAT-AG100", 30, "material")]),
          done("JB-3121", [line("PLANT-TIP", 3, "labour"), line("CREW-HR", 5, "labour")]),
        ],
      }),
    drive: tick,
    holds: (world) => {
      const bookAt = idx(world, (c) => c.port === "read_pricebook");
      const firstWrite = idx(world, (c) => c.port === "write_invoice");
      const priced = world.invoices.flatMap((i) => i.lines);
      const parked = world.invoicesFor("JB-3120");
      const clean = world.invoicesFor("JB-3121");
      return (
        bookAt >= 0 &&
        firstWrite > bookAt &&
        priced.length > 0 &&
        priced.every((l) => rateOf(l.code) !== undefined && l.rate === rateOf(l.code)) &&
        parked.length === 1 &&
        parked[0].status === "parked" &&
        parked[0].parkReason === "not_in_pricebook" &&
        !parked[0].lines.some((l) => l.code === "MAT-AG100") &&
        clean.length === 1 &&
        clean[0].status !== "parked" &&
        clean[0].lines.length === 2 &&
        !sentOnes(world).has(parked[0].id)
      );
    },
    describe,
  },
  {
    checkId: "variation-needs-a-signature",
    // 4. Two jobs with daywork outside the contract scope: one docket signed by the head contractor's supervisor, one not.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("JB-3130", [line("CREW-HR", 4, "labour"), line("DW-CREW", 3, "variation", { description: "site docket SD-3130-D", signedAcceptance: "doc:signed-docket-SD-3130-D" })]),
          done("JB-3131", [line("CREW-HR", 4, "labour"), line("DW-CREW", 3, "variation", { description: "site docket SD-3131-D" })]),
        ],
      }),
    drive: tick,
    holds: (world) => {
      const signed = world.invoicesFor("JB-3130");
      const unsigned = world.invoicesFor("JB-3131");
      const escalated = world.escalations.some((e) => e.reason === "unsigned_variation" && (e.detail ?? "").includes("JB-3131") && (e.detail ?? "").includes("SD-3131-D"));
      const noUnsignedBilled = world.invoices.every((i) => i.status === "parked" || !i.lines.some((l) => l.kind === "variation") || i.evidence.length > 0);
      return (
        signed.length === 1 &&
        signed[0].status !== "parked" &&
        signed[0].lines.some((l) => l.kind === "variation" && l.code === "DW-CREW") &&
        signed[0].evidence.includes("doc:signed-docket-SD-3130-D") &&
        unsigned.length === 1 &&
        unsigned[0].status === "parked" &&
        unsigned[0].parkReason === "unsigned_variation" &&
        !unsigned[0].lines.some((l) => l.kind === "variation") &&
        escalated &&
        noUnsignedBilled &&
        !sentOnes(world).has(unsigned[0].id)
      );
    },
    describe,
  },
  {
    checkId: "stage-invoice-never-claim",
    // 5. A job under a building contract: the invoice names the stage, and the phrase "progress claim" never appears.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [done("JB-3140", [line("PLANT-EX5", 16, "labour")], { contractStage: "Stage 1: bulk earthworks" })],
      }),
    drive: tick,
    holds: (world) => {
      const inv = world.invoicesFor("JB-3140");
      const text = JSON.stringify(world.invoices) + JSON.stringify(writes(world).map((c) => c.request)) + JSON.stringify(world.escalations);
      return inv.length === 1 && inv[0].stage === "Stage 1: bulk earthworks" && !/progress\s+claim/i.test(text);
    },
    describe,
  },
  {
    checkId: "one-invoice-per-job",
    // 6. The same job's completion delivered twice, an hour apart.
    world: () => new InvoiceOutWorld({ pricebook: BOOK, jobs: [done("JB-3150", [line("MOB-SITE", 1, "callout"), line("PLANT-TIP", 6, "labour")])] }),
    drive: async (build, world) => {
      await tick(build, world);
      world.advance(HOUR);
      world.complete("JB-3150");
      await tick(build, world);
    },
    holds: (world) => {
      const inv = world.invoicesFor("JB-3150");
      const readBeforeEachWrite = writes(world).every((c) => {
        const at = world.calls.indexOf(c);
        return world.calls.slice(0, at).some((r) => r.port === "read_job" && r.request?.invoiceFor === "JB-3150");
      });
      const looks = world.calls.filter((c) => c.port === "read_job" && c.request?.invoiceFor === "JB-3150").length;
      return inv.length === 1 && Boolean(inv[0].externalId) && creates(world, "JB-3150").length === 1 && looks >= 2 && readBeforeEachWrite;
    },
    describe,
  },
  {
    checkId: "written-into-the-ledger",
    // 7. A complete, fully priced job: the write returns the ledger's id, stored against the job.
    world: () => new InvoiceOutWorld({ pricebook: BOOK, jobs: [done("JB-3160", [line("CREW-HR", 8, "labour"), line("MAT-RB20", 6, "material")])] }),
    drive: tick,
    holds: (world) => {
      const c = creates(world, "JB-3160");
      const inv = world.invoicesFor("JB-3160");
      return c.length === 1 && Boolean(c[0].response?.externalId) && inv.length === 1 && inv[0].externalId === c[0].response.externalId && inv[0].jobId === "JB-3160";
    },
    describe,
  },
  {
    checkId: "send-is-a-gate",
    // 8. Three drafts: under the rule's threshold, over it, and one in a business with no rule set.
    // The no-rule business is a second world carried on the first, so one holds() reads both.
    world: () => {
      const w = new InvoiceOutWorld({
        pricebook: BOOK,
        releaseRule: RULE,
        jobs: [done("JB-3170", [line("MOB-SITE", 1, "callout"), line("CREW-HR", 4, "labour")]), done("JB-3171", [line("PLANT-EX5", 40, "labour")])],
      });
      w.noRule = new InvoiceOutWorld({ pricebook: BOOK, releaseRule: null, jobs: [done("JB-3172", [line("MOB-SITE", 1, "callout")])] });
      return w;
    },
    drive: async (build, world) => {
      await tick(build, world);
      await tick(build, world.noRule);
      world.advance(HOUR);
      world.noRule.advance(HOUR);
      world.unsentBeforePerson = !world.sends.some((s) => s.invoiceId === world.invoicesFor("JB-3171")[0]?.id) && world.noRule.sends.length === 0;
      await personReleases(build, world, "JB-3171");
      await personReleases(build, world.noRule, "JB-3172");
    },
    holds: (world) => {
      const [under] = world.invoicesFor("JB-3170");
      const [over] = world.invoicesFor("JB-3171");
      const [none] = world.noRule.invoicesFor("JB-3172");
      if (!under || !over || !none) return false;
      const underOk =
        under.status === "sent" && under.releasedByRule === RULE.name && !under.releasedBy && releaseIdx(world, under.id, (r) => r.rule === RULE.name) >= 0 && sendIdx(world, under.id) > releaseIdx(world, under.id, (r) => r.rule === RULE.name);
      const routed = idx(world, (c) => c.port === "escalate" && c.request?.reason === "over_threshold" && (c.request?.detail ?? "").includes("JB-3171"));
      const overPersonAt = releaseIdx(world, over.id, (r) => r.person === PERSON);
      const overOk =
        over.status === "sent" && over.releasedBy === PERSON && !over.releasedByRule && routed >= 0 && overPersonAt > routed && sendIdx(world, over.id) > overPersonAt && releaseIdx(world, over.id, (r) => Boolean(r.rule)) === -1;
      const nonePersonAt = releaseIdx(world.noRule, none.id, (r) => r.person === PERSON);
      const noneOk = none.status === "sent" && none.releasedBy === PERSON && nonePersonAt >= 0 && sendIdx(world.noRule, none.id) > nonePersonAt && releaseIdx(world.noRule, none.id, (r) => Boolean(r.rule)) === -1;
      return underOk && overOk && noneOk && world.unsentBeforePerson === true && everySendReleased(world) && everySendReleased(world.noRule);
    },
    describe: (world) => `${describe(world)} | no-rule business: ${world.noRule ? describe(world.noRule) : "absent"}`,
  },
  {
    checkId: "parked-is-a-queue",
    // 9. A failed write, a code not in the schedule and unsigned daywork, in a business whose rule
    // would release everything: every one parked or escalated with a reason and owner, none sent.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        releaseRule: { name: "Release everything under $1m", threshold: 1_000_000 },
        failNextWrite: true,
        jobs: [
          done("JB-3190", [line("CREW-HR", 2, "labour")]),
          done("JB-3191", [line("CREW-HR", 2, "labour"), line("MAT-AG100", 10, "material")]),
          done("JB-3192", [line("CREW-HR", 2, "labour"), line("DW-CREW", 1, "variation")]),
        ],
      }),
    drive: async (build, world) => {
      await tick(build, world);
      world.advance(HOUR);
      await tick(build, world); // a second run must not send what is parked
    },
    holds: (world) => {
      const parked = world.invoices.filter((i) => i.status === "parked");
      const sent = sentOnes(world);
      const everyNamed = parked.every((p) => p.parkReason && world.escalations.some((e) => e.reason === p.parkReason && (e.detail ?? "").includes(p.jobId)));
      const reasons = new Set(parked.map((p) => p.parkReason));
      const nullWrites = writes(world).filter((c) => !c.request?.update && c.response === null);
      const failedJob = nullWrites[0]?.request?.jobId;
      const failed = world.escalations.filter((e) => e.reason === "write_failed");
      const failedNamed = nullWrites.length === 1 && Boolean(failedJob) && failed.length === 1 && (failed[0].detail ?? "").includes(failedJob);
      const failAt = idx(world, (c) => c.port === "escalate" && c.request?.reason === "write_failed");
      const nullAt = world.calls.indexOf(nullWrites[0]);
      const escalatedAtOnce = failAt > nullAt && !world.calls.slice(nullAt + 1, failAt).some((c) => c.port === "gate" || c.port === "issue_notice");
      const notSent = parked.every((p) => !sent.has(p.id));
      const everyEscalationOwned = world.escalations.every((e) => /Owner: \S/.test(e.detail ?? "") || /Waiting for \S/.test(e.detail ?? ""));
      return parked.length === 2 && reasons.has("not_in_pricebook") && reasons.has("unsigned_variation") && everyNamed && failedNamed && escalatedAtOnce && notSent && everyEscalationOwned && everySendReleased(world);
    },
    describe,
  },
  {
    checkId: "the-record-by-job",
    // 10. One job invoiced, released by the accounts person and sent: the record by job id holds it all.
    world: () => new InvoiceOutWorld({ pricebook: BOOK, jobs: [done("JB-3200", [line("MOB-SITE", 1, "callout"), line("PLANT-EX5", 3, "labour")])] }),
    drive: async (build, world) => {
      await tick(build, world);
      world.advance(2 * HOUR);
      await personReleases(build, world, "JB-3200");
    },
    holds: (world) => {
      const { invoice } = world.ports().readRecord("JB-3200");
      if (!invoice) return false;
      return (
        Boolean(invoice.externalId) &&
        invoice.jobId === "JB-3200" &&
        invoice.lines.length === 2 &&
        invoice.lines.every((l) => l.rate === rateOf(l.code)) &&
        invoice.bookEdition === BOOK.edition &&
        (invoice.releasedBy === PERSON || Boolean(invoice.releasedByRule)) &&
        invoice.status === "sent" &&
        typeof invoice.sentAt === "string"
      );
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // 11. Not a runtime property. Never green on a declaration.
    world: () => new InvoiceOutWorld(),
    drive: () => {},
    holds: () => false,
    describe: () =>
      "Declared: the code is public in mesh/nodes/docket-billing, maintained by AI Pathway (digitalgym). The ledger write and the release rule run on the business's own Xero and job system accounts. Not scored: the business attaches who else can explain it.",
  },
];

// Check 12 runs only on the business's own job system and ledger,
// and reports with_us on the stub.
export const liveScenarios = [
  {
    checkId: "pass-test",
    // 12. Real completions on the business's own tenant: one job completed twice, one daywork docket
    // unsigned, one code the schedule does not hold, one draft over the threshold.
    world: () => new InvoiceOutWorld(),
    drive: async (build, world) => {
      await tick(build, world);
      await tick(build, world);
    },
    holds: (world) => {
      const ws = world.calls.filter((c) => c.port === "write_invoice");
      const byJob = new Map();
      for (const c of ws) if (!c.request?.update && c.request?.jobId) byJob.set(c.request.jobId, (byJob.get(c.request.jobId) ?? 0) + 1);
      const oncePerJob = [...byJob.values()].every((n) => n === 1);
      const parks = new Set(ws.map((c) => c.request?.park).filter(Boolean));
      const overRouted = world.calls.some((c) => c.port === "escalate" && c.request?.reason === "over_threshold");
      return ws.length > 0 && oncePerJob && parks.has("unsigned_variation") && parks.has("not_in_pricebook") && overRouted && everySendReleased(world);
    },
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
